/* ============================================
   PAGINATION COMPONENT
   Page navigation for long datasets
   ============================================ */

.ds-pagination {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-100); /* 4px */
}

.ds-pagination__list {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-100); /* 4px */
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ============================================
   PAGE BUTTONS
   Pill-shaped, matching CircularButton sizing
   ============================================ */

.ds-pagination__page,
.ds-pagination__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill); /* pill */
  background-color: transparent;
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), color var(--motion-duration-base) var(--motion-ease-standard);
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-secondary);
}

.ds-pagination__page:hover:not(:disabled):not(.ds-pagination__page--current),
.ds-pagination__arrow:hover:not(:disabled) {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-pagination__page:focus-visible,
.ds-pagination__arrow:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   CURRENT PAGE
   Same active treatment as SegmentedControl
   ============================================ */

.ds-pagination__page--current {
  background-color: var(--color-action-primary-bg);
  color: var(--color-action-primary-text);
}

.ds-pagination__page--current:hover {
  background-color: var(--color-action-primary-bg-hover);
}

/* ============================================
   ARROWS
   ============================================ */

.ds-pagination__icon {
  --icon-size: var(--icon-size-600);
  line-height: 1;
  color: var(--color-icon-primary);
}

.ds-pagination__arrow:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   ELLIPSIS
   ============================================ */

.ds-pagination__ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  color: var(--color-text-tertiary);
  user-select: none;
}

/* ============================================
   COMPACT
   Prev/next arrows with a page readout
   ============================================ */

.ds-pagination--compact .ds-pagination__arrow {
  width: 32px;
  height: 32px;
}

.ds-pagination--compact .ds-pagination__icon {
  --icon-size: var(--icon-size-500);
}

.ds-pagination__readout {
  padding: 0 var(--padding-200); /* 8px */
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);
  white-space: nowrap;
}

'use client';

import './Pagination.css';
import '../../fonts/material-symbols.css';

export interface PaginationProps {
  /** Current page (1-based) */
  page: number;
  /** Total number of pages */
  pageCount: number;
  /** Callback with the requested page */
  onPageChange: (page: number) => void;
  /** Pages shown on each side of the current page */
  siblingCount?: number;
  /** Component size — compact swaps the numbers for a "Page X of Y" readout */
  size?: 'default' | 'compact';
  /** Accessible label for the nav landmark */
  ariaLabel?: string;
  /** Additional CSS classes */
  className?: string;
}

type PageItem = number | 'start-ellipsis' | 'end-ellipsis';

const range = (start: number, end: number) =>
  Array.from({ length: end - start + 1 }, (_, i) => start + i);

/** Build the visible page list: first/last always shown, ellipses for gaps */
const getPageItems = (
  page: number,
  pageCount: number,
  siblingCount: number
): PageItem[] => {
  const totalNumbers = siblingCount * 2 + 5; // first + last + current + 2 ellipsis slots

  if (pageCount <= totalNumbers) {
    return range(1, pageCount);
  }

  const leftSibling = Math.max(page - siblingCount, 1);
  const rightSibling = Math.min(page + siblingCount, pageCount);
  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < pageCount - 1;

  if (!showLeftEllipsis && showRightEllipsis) {
    return [...range(1, 3 + 2 * siblingCount), 'end-ellipsis', pageCount];
  }

  if (showLeftEllipsis && !showRightEllipsis) {
    return [1, 'start-ellipsis', ...range(pageCount - (2 + 2 * siblingCount), pageCount)];
  }

  return [1, 'start-ellipsis', ...range(leftSibling, rightSibling), 'end-ellipsis', pageCount];
};

/**
 * Pagination component — page navigation for long datasets.
 * Numbered pages with ellipses for large ranges, or a compact
 * prev/next readout. Pairs with Table.
 */
export const Pagination = ({
  page,
  pageCount,
  onPageChange,
  siblingCount = 1,
  size = 'default',
  ariaLabel = 'Pagination',
  className = '',
}: PaginationProps) => {
  const baseClass = 'ds-pagination';
  const compact = size === 'compact';

  const clampedPage = Math.min(Math.max(page, 1), Math.max(pageCount, 1));
  const isFirst = clampedPage <= 1;
  const isLast = clampedPage >= pageCount;

  const goTo = (target: number) => {
    const next = Math.min(Math.max(target, 1), pageCount);
    if (next !== clampedPage) onPageChange(next);
  };

  const classes = [baseClass, compact ? `${baseClass}--compact` : '', className]
    .filter(Boolean)
    .join(' ');

  const arrowButton = (direction: 'previous' | 'next') => {
    const disabled = direction === 'previous' ? isFirst : isLast;
    return (
      <button
        type="button"
        className={`${baseClass}__arrow`}
        onClick={() => goTo(direction === 'previous' ? clampedPage - 1 : clampedPage + 1)}
        disabled={disabled}
        aria-label={direction === 'previous' ? 'Previous page' : 'Next page'}
      >
        <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
          {direction === 'previous' ? 'chevron_left' : 'chevron_right'}
        </span>
      </button>
    );
  };

  return (
    <nav className={classes} aria-label={ariaLabel}>
      {arrowButton('previous')}

      {compact ? (
        <span className={`${baseClass}__readout`} aria-live="polite">
          Page {clampedPage} of {pageCount}
        </span>
      ) : (
        <ul className={`${baseClass}__list`}>
          {getPageItems(clampedPage, pageCount, siblingCount).map((item) =>
            typeof item === 'number' ? (
              <li key={item}>
                <button
                  type="button"
                  className={[
                    `${baseClass}__page`,
                    item === clampedPage ? `${baseClass}__page--current` : '',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                  onClick={() => goTo(item)}
                  aria-current={item === clampedPage ? 'page' : undefined}
                  aria-label={`Page ${item}`}
                >
                  {item}
                </button>
              </li>
            ) : (
              <li key={item}>
                <span className={`${baseClass}__ellipsis`} aria-hidden="true">
                  &#8230;
                </span>
              </li>
            )
          )}
        </ul>
      )}

      {arrowButton('next')}
    </nav>
  );
};
